(1949072, 268490, 22379, '<td valign="top">Blurry moving vechical shots are not that visually interesting or appealing. This is no exception, sorry.</td>', 'Blurry moving vechical shots are not that visually interesting or appealing. This is no exception, sorry.', '2005-12-14 00:22:59.000000', NULL, 1),
(1949084, 267686, 22379, '<td valign="top">The title indicates there is a story to tell, yet all we can see is a bald hedge. Could therehave been a better picture on the other side of that hedge?</td>', 'The title indicates there is a story to tell, yet all we can see is a bald hedge. Could therehave been a better picture on the other side of that hedge?', '2005-12-14 00:25:00.000000', NULL, 1),
(1949086, 268321, 40106, '<td valign="top">will ribbon...no doubt</td>', 'will ribbon...no doubt', '2005-12-14 00:25:18.000000', NULL, 1),
(1949094, 268451, 22379, '<td valign="top">This image has the unfortunate signs of a snapshot. <br/>A could of ideas pop into my head for how it could have been improves. * getting closer to the rails so you could position the camera against them so not to include them in the picture. * situate yourself at an angle that the patterns between the rails complimented santa instead of serving as a distraction.* angling the camera so that it appears like santa is flyingupwards.</td>', 'This image has the unfortunate signs of a snapshot. A could of ideas pop into my head for how it could have been improves. * getting closer to the rails so you could position the camera against them so not to include them in the picture. * situate yourself at an angle that the patterns between the rails complimented santa instead of serving as a distraction.* angling the camera so that it appears like santa is flyingupwards.', '2005-12-14 00:27:26.000000', NULL, 1),
