(1953932, 268712, 32644, '<td valign="top">This is simply beautiful. It looks like the horizon is off a little but I''m not sure - could be the hills beyond the water.</td>', 'This is simply beautiful. It looks like the horizon is off a little but I''m not sure - could be the hills beyond the water.', '2005-12-15 12:32:50.000000', NULL, 1),
(1953935, 267035, 32644, '<td valign="top">very nice colors and composition. Beautiful!</td>', 'very nice colors and composition. Beautiful!', '2005-12-15 12:34:48.000000', NULL, 1),
(1953936, 268696, 32644, '<td valign="top">I like this for the dim lighting. Beautiful Beta.</td>', 'I like this for the dim lighting. Beautiful Beta.', '2005-12-15 12:34:58.000000', NULL, 1),
(1953939, 266868, 32644, '<td valign="top">Nice composition and lighting.</td>', 'Nice composition and lighting.', '2005-12-15 12:36:00.000000', NULL, 1),
(1953943, 267110, 32644, '<td valign="top">This is very beautiful. The stars make it perfect!</td>', 'This is very beautiful. The stars make it perfect!', '2005-12-15 12:37:20.000000', NULL, 1),
(1953947, 268348, 32644, '<td valign="top">This is amazing. I wish it were bigger.</td>', 'This is amazing. I wish it were bigger.', '2005-12-15 12:39:24.000000', NULL, 1),
(1953954, 268857, 32644, '<td valign="top">WOW. Great shot above the clouds. Needs to be rotated a little to straighten the horizon and your camera appears to have something on the sensor. Check other pictures to see if it shows up in the same area.</td>', 'WOW. Great shot above the clouds. Needs to be rotated a little to straighten the horizon and your camera appears to have something on the sensor. Check other pictures to see if it shows up in the same area.', '2005-12-15 12:42:38.000000', NULL, 1),
(1953960, 268848, 32644, '<td valign="top">Wow that is some bright moonlight!</td>', 'Wow that is some bright moonlight!', '2005-12-15 12:44:14.000000', NULL, 1),
(1953963, 267683, 32644, '<td valign="top">OK, this is just lazy. Credit for waking up and entering the challenge.</td>', 'OK, this is just lazy. Credit for waking up and entering the challenge.', '2005-12-15 12:45:16.000000', NULL, 1),
(1953965, 267236, 32644, '<td valign="top">Too cold outside?</td>', 'Too cold outside?', '2005-12-15 12:45:57.000000', NULL, 1),
