(1953974, 268865, 9253, '<td valign="top">I loved this shot. Great job! Hope you win a ribbon.</td>', 'I loved this shot. Great job! Hope you win a ribbon.', '2005-12-15 12:48:52.000000', NULL, 1),
(1953975, 267900, 32644, '<td valign="top">Are you two using the same telescope? Beautiful shot. Doesn''t seem quite as sharp as the other entry.</td>', 'Are you two using the same telescope? Beautiful shot. Doesn''t seem quite as sharp as the other entry.', '2005-12-15 12:49:37.000000', NULL, 1),
