(1958736, 268883, 49763, '<td valign="top">This picture is my favorite thus far and I''ve already seen thirty or so. This raptor is in rare form as the subject. Amazing. 10</td>', 'This picture is my favorite thus far and I''ve already seen thirty or so. This raptor is in rare form as the subject. Amazing. 10', '2005-12-17 17:28:14.000000', NULL, 1),
(1958738, 268588, 44963, '<td valign="top">Top shot - You seem to have used the available light well and composed a photo that draws the viewer in.  I hope you do well in the challenge.</td>', 'Top shot - You seem to have used the available light well and composed a photo that draws the viewer in.  I hope you do well in the challenge.', '2005-12-17 17:28:52.000000', NULL, 1),
(1958740, 268856, 49763, '<td valign="top">Yes, the sand man has already payed his visit. A good photo.</td>', 'Yes, the sand man has already payed his visit. A good photo.', '2005-12-17 17:29:05.000000', NULL, 1),
(1958741, 268883, 44963, '<td valign="top">What a stunning image.  Isn''t timing everything.  The sky and the bird captured in perfect combination.</td>', 'What a stunning image.  Isn''t timing everything.  The sky and the bird captured in perfect combination.', '2005-12-17 17:30:27.000000', NULL, 1),
