(1958748, 268936, 21894, '<td valign="top">nice photograph... i like the composition and the lighting good job</td>', 'nice photograph... i like the composition and the lighting good job', '2005-12-17 17:32:09.000000', NULL, 1),
(1958749, 268889, 44963, '<td valign="top">The colour attracted me to this image.  More so that merely the contrast between sky and snow - it is the hue created by the lighting that gives the image an abandond look.  Thanks.</td>', 'The colour attracted me to this image.  More so that merely the contrast between sky and snow - it is the hue created by the lighting that gives the image an abandond look.  Thanks.', '2005-12-17 17:32:25.000000', NULL, 1),
