INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1959472, 267897, 37818, '<td valign="top">Well I gotta score ya high. Not only do I like this shot, I can relate, I am a Pastry Chef :) It looks a little too familiar!</td>', 'Well I gotta score ya high. Not only do I like this shot, I can relate, I am a Pastry Chef :) It looks a little too familiar!', '2005-12-18 00:27:14.000000', NULL, 1),
(1959494, 268416, 45961, '<td valign="top">Definitely as the title says. Very grainy and unfocused. I don''t mean to criticise, since I''m a horrible photographer. I gave a 3 on this because of the whole quality of the composition. With of course a few points meeting the challenge. I don''t think it fits the challenge very well at all. I just can''t grasp the concept of it. I applaud for the effort though. The picture is a bit too dark as well. Sorry.</td>', 'Definitely as the title says. Very grainy and unfocused. I don''t mean to criticise, since I''m a horrible photographer. I gave a 3 on this because of the whole quality of the composition. With of course a few points meeting the challenge. I don''t think it fits the challenge very well at all. I just can''t grasp the concept of it. I applaud for the effort though. The picture is a bit too dark as well. Sorry.', '2005-12-18 01:01:52.000000', NULL, 1),
(1959530, 267185, 34217, '<td valign="top">there is not enough detail.  You should have used a longer exposure</td>', 'there is not enough detail.  You should have used a longer exposure', '2005-12-18 01:39:08.000000', NULL, 1),
(1959531, 268877, 34217, '<td valign="top">looks like you have some camera shake here.</td>', 'looks like you have some camera shake here.', '2005-12-18 01:40:43.000000', NULL, 1),
(1959533, 268860, 34217, '<td valign="top">kinda boring, sorry</td>', 'kinda boring, sorry', '2005-12-18 01:41:32.000000', NULL, 1),
(1959535, 267126, 34217, '<td valign="top">you need to make the shape more obvious</td>', 'you need to make the shape more obvious', '2005-12-18 01:43:17.000000', NULL, 1),
(1959573, 268939, 49763, '<td valign="top">This picure stands alone in this competetion as a masterpiece of early morning light. It seems the advantage was a earlier sunrise than many of the other locals. It is a devine photo. 9</td>', 'This picure stands alone in this competetion as a masterpiece of early morning light. It seems the advantage was a earlier sunrise than many of the other locals. It is a devine photo. 9', '2005-12-18 02:34:59.000000', NULL, 1),
(1959575, 268709, 49763, '<td valign="top">This right to left view of the moon is in interesting contrast to the other entered in this challenge. I can not say with assuredness which is better. This is a powerful picture. 8</td>', 'This right to left view of the moon is in interesting contrast to the other entered in this challenge. I can not say with assuredness which is better. This is a powerful picture. 8', '2005-12-18 02:37:27.000000', NULL, 1),
(1959578, 267687, 49763, '<td valign="top">The haze and the choice of vertical composition are astounding in their beauty. This is a winner of a photograph. 9</td>', 'The haze and the choice of vertical composition are astounding in their beauty. This is a winner of a photograph. 9', '2005-12-18 02:38:58.000000', NULL, 1),
(1959581, 268348, 49763, '<td valign="top">One of those naturally beautiful places in nature. I am amzed at the warm feeling this image creates throught its subject of steam on the water.</td>', 'One of those naturally beautiful places in nature. I am amzed at the warm feeling this image creates throught its subject of steam on the water.', '2005-12-18 02:40:52.000000', NULL, 1),
(1959584, 267112, 49763, '<td valign="top">The dark shape coming out of the neck of the bottle is a highlight of this composition. Other peaks include the shadow of the bottle and lighting cast on the folded scrap of paper. I can also relate to this picture as I have truely sleep on many a floor and/or doorstep. Great 9</td>', 'The dark shape coming out of the neck of the bottle is a highlight of this composition. Other peaks include the shadow of the bottle and lighting cast on the folded scrap of paper. I can also relate to this picture as I have truely sleep on many a floor and/or doorstep. Great 9', '2005-12-18 02:44:12.000000', NULL, 1),
(1959589, 268694, 49763, '<td valign="top">Such bright lights at four in the morning are not always welcome and a rough prohibition such as this is often the last thing you would appreciate. I am impressed with your choice of subject and the stark beauty of that corner. The angles in this photo are to die for. 9</td>', 'Such bright lights at four in the morning are not always welcome and a rough prohibition such as this is often the last thing you would appreciate. I am impressed with your choice of subject and the stark beauty of that corner. The angles in this photo are to die for. 9', '2005-12-18 02:46:53.000000', NULL, 1),
(1959593, 269014, 49763, '<td valign="top">It seems windswept and yet so still. This is beauty unto its self. Words can not express the wisdom required to discover such a subject in its naturally beautiful form. 10</td>', 'It seems windswept and yet so still. This is beauty unto its self. Words can not express the wisdom required to discover such a subject in its naturally beautiful form. 10', '2005-12-18 02:49:00.000000', NULL, 1),
(1959597, 268598, 49763, '<td valign="top">A mood caught on this street borders on the melancholic. The work that has been done to the original picure has only, and seemingly could only, have done good. It is a beautiful image. 9</td>', 'A mood caught on this street borders on the melancholic. The work that has been done to the original picure has only, and seemingly could only, have done good. It is a beautiful image. 9', '2005-12-18 02:51:55.000000', NULL, 1),
(1959599, 268671, 49763, '<td valign="top">Genius. The name and more over the subject are worthy of high praise. The lack of balance and the capturing of light are equally respectable. Splendid. 8</td>', 'Genius. The name and more over the subject are worthy of high praise. The lack of balance and the capturing of light are equally respectable. Splendid. 8', '2005-12-18 02:54:01.000000', NULL, 1),
