(1964013, 266569, 47316, '<td valign="top">Nice shot, work on your cropping, I don''t think you should have cut their feet off... perhaps even a closer shot would have been better.</td>', 'Nice shot, work on your cropping, I don''t think you should have cut their feet off... perhaps even a closer shot would have been better.', '2005-12-19 23:55:28.000000', NULL, 1),
(1964183, 267110, 9089, '<td valign="top">Wow, this is a truly amazing photograph.  It has such a masterpiece painting feel to it.  The colors, composition, reflections, and the starlights in the sky just all work together to make a photo that begs to be blown up to poster size and mounted in a really nice frame ona wall someplace.  Honestly, if this doesn''t ribbon, there is something wrong with this site.  Thanks for taking a picture that is truly inspiring.</td>', 'Wow, this is a truly amazing photograph.  It has such a masterpiece painting feel to it.  The colors, composition, reflections, and the starlights in the sky just all work together to make a photo that begs to be blown up to poster size and mounted in a really nice frame ona wall someplace.  Honestly, if this doesn''t ribbon, there is something wrong with this site.  Thanks for taking a picture that is truly inspiring.', '2005-12-20 02:13:04.000000', NULL, 1),
(1964340, 266940, 23394, '<td valign="top">very nice idea.  maybe could have used a more dramatic pose, like bending over to grab one of those beers, or to get something out of the back of the fridge, but, then again, at that time of night, there is usually that sense of uncertainty, wanting something, but not knowing just what.  great work!  love the lighting--that is tops.  great perspective, as well.</td>', 'very nice idea.  maybe could have used a more dramatic pose, like bending over to grab one of those beers, or to get something out of the back of the fridge, but, then again, at that time of night, there is usually that sense of uncertainty, wanting something, but not knowing just what.  great work!  love the lighting--that is tops.  great perspective, as well.', '2005-12-20 04:15:44.000000', NULL, 1),
(1964353, 268478, 23394, '<td valign="top">i almost missed the person!  excellent capture--it feels COLD!  hats off to you for getting out there.  if i was going to nit-pick, i''d say the image is a bit soft, as if you needed a remote-release for your shutter.</td>', 'i almost missed the person!  excellent capture--it feels COLD!  hats off to you for getting out there.  if i was going to nit-pick, i''d say the image is a bit soft, as if you needed a remote-release for your shutter.', '2005-12-20 04:20:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1964359, 268939, 23394, '<td valign="top">lovely colors.  love the hint of dawnish-lighting in the clouds above the roof.  probably could have used just a bit more of that.  this has a nice ''van gogh'' feel to it.  nice work.</td>', 'lovely colors.  love the hint of dawnish-lighting in the clouds above the roof.  probably could have used just a bit more of that.  this has a nice ''van gogh'' feel to it.  nice work.', '2005-12-20 04:22:46.000000', NULL, 1),
(1964366, 268442, 23394, '<td valign="top">can''t quite put my finger on it, but this seems a bit out of balance.  probably needs to be rotated slightly to the left.  the colors left by the lighting make me feel this would be stronger as a bw.</td>', 'can''t quite put my finger on it, but this seems a bit out of balance.  probably needs to be rotated slightly to the left.  the colors left by the lighting make me feel this would be stronger as a bw.', '2005-12-20 04:24:41.000000', NULL, 1),
(1964368, 268588, 23394, '<td valign="top">looks suspiciously like a match factory, except for the caskets.  this could probably be more interesting if there was a person or some people shuffling by on there way to work.  if you''re working off a tripod and there''s no one around, don''t be afraid to insert yourself into a few shots just to see how they come out.</td>', 'looks suspiciously like a match factory, except for the caskets.  this could probably be more interesting if there was a person or some people shuffling by on there way to work.  if you''re working off a tripod and there''s no one around, don''t be afraid to insert yourself into a few shots just to see how they come out.', '2005-12-20 04:26:35.000000', NULL, 1),
(1964376, 266285, 23394, '<td valign="top">you really need to take advantage of submitting images to the full size allowed by dpc.  there are some great colors here, but most of your detail is lost in the smallish size.  i scored this a 6 just for the colors and meeting the challenge.  i think you have potential, but you are really going to have to push yourself.  for all intents and purposes, this is a snapshot.  there is no true subject that helps the picture tell a story.  from the looks of things, there probably were some interesting things to be photographed here.</td>', 'you really need to take advantage of submitting images to the full size allowed by dpc.  there are some great colors here, but most of your detail is lost in the smallish size.  i scored this a 6 just for the colors and meeting the challenge.  i think you have potential, but you are really going to have to push yourself.  for all intents and purposes, this is a snapshot.  there is no true subject that helps the picture tell a story.  from the looks of things, there probably were some interesting things to be photographed here.', '2005-12-20 04:30:17.000000', NULL, 1),
(1964377, 268709, 23394, '<td valign="top">very, very nice.  thanks for the trip!</td>', 'very, very nice.  thanks for the trip!', '2005-12-20 04:30:48.000000', NULL, 1),
(1964380, 268142, 23394, '<td valign="top">the tilt and coloring do not help this.  i''m scoring it a 6 just because you went out in the cold.  would probably have scored it higher if the image made me feel you had stayed out a bit longer to try and make a more interesting image.</td>', 'the tilt and coloring do not help this.  i''m scoring it a 6 just because you went out in the cold.  would probably have scored it higher if the image made me feel you had stayed out a bit longer to try and make a more interesting image.', '2005-12-20 04:32:28.000000', NULL, 1),
(1964387, 268490, 23394, '<td valign="top">ok, i scored this a 6 the first time through and i''ll leave it at that.  now that i''m spending a bit more time with it, i think this needs a lot of work.  nothing''s in focus  the colors aren''t that great.  the composition of the lines are what does work.  i like this type of shot, and do hope you''ll go back and practice this some more.</td>', 'ok, i scored this a 6 the first time through and i''ll leave it at that.  now that i''m spending a bit more time with it, i think this needs a lot of work.  nothing''s in focus  the colors aren''t that great.  the composition of the lines are what does work.  i like this type of shot, and do hope you''ll go back and practice this some more.', '2005-12-20 04:37:17.000000', NULL, 1),
(1964390, 268972, 23394, '<td valign="top">tough shot to get.  love the feeling of a cold middle night.</td>', 'tough shot to get.  love the feeling of a cold middle night.', '2005-12-20 04:39:14.000000', NULL, 1),
(1964393, 268693, 23394, '<td valign="top">cold and alone.  poignant image.  looks like it could stand a little more work post-processing, to really give it some kick.</td>', 'cold and alone.  poignant image.  looks like it could stand a little more work post-processing, to really give it some kick.', '2005-12-20 04:40:46.000000', NULL, 1),
(1964395, 268877, 23394, '<td valign="top">nice idea, but it looks like something bumped your camera.  i''ll score it a 6, but would have scored it higher if it was sharper.</td>', 'nice idea, but it looks like something bumped your camera.  i''ll score it a 6, but would have scored it higher if it was sharper.', '2005-12-20 04:42:34.000000', NULL, 1),
(1964399, 266467, 23394, '<td valign="top">not sure how your title fits the image...<br/> <br/>without a subject, this is not that interesting an image to me.  i''ll give you a 6 just for getting out into the cold, but don''t really see anything here to take me beyond that.</td>', 'not sure how your title fits the image... without a subject, this is not that interesting an image to me.  i''ll give you a 6 just for getting out into the cold, but don''t really see anything here to take me beyond that.', '2005-12-20 04:44:35.000000', NULL, 1),
(1964407, 268624, 23394, '<td valign="top">when i made my first pass, i almost commented  ''i wonder how many people will be able to relate to the lighting here at this time of morning?''  and now that i see the validation flag, i guess the answer to my question is ''at least one'' ;-)  i don''t know if you captured this best angle here, but then again, at that time of morning, in the cold, at this particular place, i don''t know how many long exposure shots i would be trying, either...</td>', 'when i made my first pass, i almost commented  ''i wonder how many people will be able to relate to the lighting here at this time of morning?''  and now that i see the validation flag, i guess the answer to my question is ''at least one'' ;-)  i don''t know if you captured this best angle here, but then again, at that time of morning, in the cold, at this particular place, i don''t know how many long exposure shots i would be trying, either...', '2005-12-20 04:49:03.000000', NULL, 1),
(1964411, 266868, 23394, '<td valign="top">nicely observed, but doesn''t really give me any sense of context as to time.  with the lighting as it is, this might have been stronger as a bw.</td>', 'nicely observed, but doesn''t really give me any sense of context as to time.  with the lighting as it is, this might have been stronger as a bw.', '2005-12-20 04:50:34.000000', NULL, 1),
(1964417, 267671, 23394, '<td valign="top">so, who''s your shooting buddy...<br/> <br/>well, i like the colors in yours better, but i wish it wasn''t so soft.  all the same, i''m giving ya''ll both the same score, because far be it from me to get in the middle.  bet ya''ll had a fun week comparing scores, as well ;-)</td>', 'so, who''s your shooting buddy... well, i like the colors in yours better, but i wish it wasn''t so soft.  all the same, i''m giving ya''ll both the same score, because far be it from me to get in the middle.  bet ya''ll had a fun week comparing scores, as well ;-)', '2005-12-20 04:54:16.000000', NULL, 1),
(1964421, 267035, 23394, '<td valign="top">gorgeous.  glad i came back to comment so that i can bump this one up.  you must have really enjoyed this moment.  thanks for sharing it.<br/> <br/>well, i just found that you already shared this moment ;-)  hope you''ve had a fun week comparing scores...</td>', 'gorgeous.  glad i came back to comment so that i can bump this one up.  you must have really enjoyed this moment.  thanks for sharing it. well, i just found that you already shared this moment ;-)  hope you''ve had a fun week comparing scores...', '2005-12-20 04:55:13.000000', NULL, 1),
(1964431, 266569, 23394, '<td valign="top">yes, bw is best when lighting is bad.  no, snow and flash do not mix well.  yes, it was probably cold, but i''m sure your subjects would not have minded working on this a bit longer.  if you just happened upon them, then this might be the best you could do.  if they were out there for you, you probably could have composed a more interesting image, as well as taken a few where the snow blobs didn''t steal most of the attention.</td>', 'yes, bw is best when lighting is bad.  no, snow and flash do not mix well.  yes, it was probably cold, but i''m sure your subjects would not have minded working on this a bit longer.  if you just happened upon them, then this might be the best you could do.  if they were out there for you, you probably could have composed a more interesting image, as well as taken a few where the snow blobs didn''t steal most of the attention.', '2005-12-20 05:03:03.000000', NULL, 1),
(1964435, 268696, 23394, '<td valign="top">this is an ok image, but not interesting enough to me to even consider how it fits the challenge.  maybe if you had shot up through those marbles or something else to give the image spark.  nice colors, though.</td>', 'this is an ok image, but not interesting enough to me to even consider how it fits the challenge.  maybe if you had shot up through those marbles or something else to give the image spark.  nice colors, though.', '2005-12-20 05:06:27.000000', NULL, 1),
(1964441, 267126, 23394, '<td valign="top">without the title, i wouldn''t find any connection to the challenge.  as an image, it is ok.  i like the colors and i like the idea, but find the execution weak.  the position of the subjects just doesn''t tell me much.  i could guess this is a father holding his daughter, being lit by a night-light, but there''s just not enough there.  maybe if her feet were showing, as if he were cradling her?  yes, titles are part of the image, but the better images can stand on their own.</td>', 'without the title, i wouldn''t find any connection to the challenge.  as an image, it is ok.  i like the colors and i like the idea, but find the execution weak.  the position of the subjects just doesn''t tell me much.  i could guess this is a father holding his daughter, being lit by a night-light, but there''s just not enough there.  maybe if her feet were showing, as if he were cradling her?  yes, titles are part of the image, but the better images can stand on their own.', '2005-12-20 05:10:15.000000', NULL, 1),
(1964446, 268573, 23394, '<td valign="top">so, you got up in the middle of the night and went out into the cold to take a picture for the challenge.  i''m not finding anything here that tells me what you were after.  the tire tracks could be interesting, but this would need a bit more processing to bring them out.  other than that, i''m not seeing much of interest.  was there something about this that really grabbed you, or did you just want to have something in the challenge?  you don''t have to answer me, but you should answer that for yourself...</td>', 'so, you got up in the middle of the night and went out into the cold to take a picture for the challenge.  i''m not finding anything here that tells me what you were after.  the tire tracks could be interesting, but this would need a bit more processing to bring them out.  other than that, i''m not seeing much of interest.  was there something about this that really grabbed you, or did you just want to have something in the challenge?  you don''t have to answer me, but you should answer that for yourself...', '2005-12-20 05:14:32.000000', NULL, 1),
(1964450, 266361, 23394, '<td valign="top">the color cast by this lighting really detracts.  this would probably have more impact in bw.  that light is also extremely annoying, and really takes away from being able to look at much of the rest of the image.  i get the idea, but think it could still use some work.</td>', 'the color cast by this lighting really detracts.  this would probably have more impact in bw.  that light is also extremely annoying, and really takes away from being able to look at much of the rest of the image.  i get the idea, but think it could still use some work.', '2005-12-20 05:16:49.000000', NULL, 1),
(1964470, 268860, 8522, '<td valign="top">Photo is OOF, bottom horizontal is not level. You need to be exactly straight on for this to work. Although subject matter may mean something to you, I find it very uninspired. Terrible quality of lighting/ white balance.</td>', 'Photo is OOF, bottom horizontal is not level. You need to be exactly straight on for this to work. Although subject matter may mean something to you, I find it very uninspired. Terrible quality of lighting/ white balance.', '2005-12-20 06:12:13.000000', NULL, 1),
(1964472, 268623, 8522, '<td valign="top">I''m always a sucker for this composition (usually tunnel with person about to cross exit). Grain is effective. Good choice of shutter speed. Table and chairs really make this shot interesting.</td>', 'I''m always a sucker for this composition (usually tunnel with person about to cross exit). Grain is effective. Good choice of shutter speed. Table and chairs really make this shot interesting.', '2005-12-20 06:13:24.000000', NULL, 1),
(1964473, 268839, 8522, '<td valign="top">OOF. Composition seems unbalanced.</td>', 'OOF. Composition seems unbalanced.', '2005-12-20 06:13:53.000000', NULL, 1),
(1964475, 267123, 8522, '<td valign="top">Silhouette needs to be razor sharp for this photo to work, it looks like this is out of focus. Nice composition though.</td>', 'Silhouette needs to be razor sharp for this photo to work, it looks like this is out of focus. Nice composition though.', '2005-12-20 06:14:38.000000', NULL, 1),
(1964476, 268694, 8522, '<td valign="top">Doesn''t say early morning to me.</td>', 'Doesn''t say early morning to me.', '2005-12-20 06:14:53.000000', NULL, 1),
(1964478, 268915, 8522, '<td valign="top">Nice idea for this challenge, light at top of fridge is too bright for me here. Perhaps if you''d been to her left and shown her face lit up by that same light this could have worked much better. Compositionally feels unbalanced... rule of thirds?</td>', 'Nice idea for this challenge, light at top of fridge is too bright for me here. Perhaps if you''d been to her left and shown her face lit up by that same light this could have worked much better. Compositionally feels unbalanced... rule of thirds?', '2005-12-20 06:16:21.000000', NULL, 1),
(1964480, 267024, 8522, '<td valign="top">Nice idea, not sure about his placement in the frame. I think if his eyes obeyed rule of thirds this could have been more effective. Shame his torso is overexposed. Background is too bright, it takes attention away from the subject.</td>', 'Nice idea, not sure about his placement in the frame. I think if his eyes obeyed rule of thirds this could have been more effective. Shame his torso is overexposed. Background is too bright, it takes attention away from the subject.', '2005-12-20 06:18:06.000000', NULL, 1),
(1964481, 269021, 8522, '<td valign="top">I can see someone on the ground, but other than that I''m really not sure what I''m looking at here. The photo needs to tell more of a clear story IMO.</td>', 'I can see someone on the ground, but other than that I''m really not sure what I''m looking at here. The photo needs to tell more of a clear story IMO.', '2005-12-20 06:18:58.000000', NULL, 1),
(1964483, 268876, 8522, '<td valign="top">Without the title, this wouldn''t tell much of a story to me. I think the bottles need more context. Shallow dof doesn''t look deliberate enough to me. Why have you focused on the middle one? Although the subject may be meaningful to you, visually it looks dull and uninspired... I don''t think you''ve really SEEN what you''re taking a photo of here other than bottles for your baby. What do they really LOOK like?</td>', 'Without the title, this wouldn''t tell much of a story to me. I think the bottles need more context. Shallow dof doesn''t look deliberate enough to me. Why have you focused on the middle one? Although the subject may be meaningful to you, visually it looks dull and uninspired... I don''t think you''ve really SEEN what you''re taking a photo of here other than bottles for your baby. What do they really LOOK like?', '2005-12-20 06:21:02.000000', NULL, 1),
(1964484, 268671, 8522, '<td valign="top">Doesn''t give a sense of early morning to me. Isn''t that when lights like these are turned off?</td>', 'Doesn''t give a sense of early morning to me. Isn''t that when lights like these are turned off?', '2005-12-20 06:21:33.000000', NULL, 1),
(1964492, 268321, 48702, '<td valign="top">Poor guy.</td>', 'Poor guy.', '2005-12-20 06:27:32.000000', NULL, 1),
(1964498, 267900, 8522, '<td valign="top">Doesn''t seem quite sharp enough. Although moon shots can be fun, I''ve seen so many that you need something unusual or different to stand out if you enter them into a competition. The composition here really doesn''t say anything new to me.</td>', 'Doesn''t seem quite sharp enough. Although moon shots can be fun, I''ve seen so many that you need something unusual or different to stand out if you enter them into a competition. The composition here really doesn''t say anything new to me.', '2005-12-20 07:01:11.000000', NULL, 1),
(1964499, 268853, 8522, '<td valign="top">Nice idea, but the composition doesn''t seem inspired. What about rule of thirds to help? White balance seems wrong.</td>', 'Nice idea, but the composition doesn''t seem inspired. What about rule of thirds to help? White balance seems wrong.', '2005-12-20 07:01:54.000000', NULL, 1),
(1964500, 268443, 8522, '<td valign="top">I see a church, I don''t see WHY you took a photo of the church. Nothing here lifts this above a snapshot. Lighting isn''t great. Verticals aren''t straight. Composition isn''t inspired... have you come across rule of thirds?</td>', 'I see a church, I don''t see WHY you took a photo of the church. Nothing here lifts this above a snapshot. Lighting isn''t great. Verticals aren''t straight. Composition isn''t inspired... have you come across rule of thirds?', '2005-12-20 07:03:46.000000', NULL, 1),
(1964501, 266704, 8522, '<td valign="top">The hand with water could be much clearer, it took me a while to spot what was going on in this photo. Nice light, although I think the white balance is a little off.</td>', 'The hand with water could be much clearer, it took me a while to spot what was going on in this photo. Nice light, although I think the white balance is a little off.', '2005-12-20 07:05:02.000000', NULL, 1),
(1964504, 269022, 8522, '<td valign="top">Nice clock, but you need to develop your photographic eye. Did you think about the texture on the wall? The shadow cast by your light source? The glare caused by the light source? All these things take away from this shot. But the main question is why would we want to look at a centered composition of a clock?What story does it tell? ''Look Ma, I met the challenge'' is just not enough! Photography like this is perhaps good enough if you want to sell something on Ebay. If you want to be a photographer, look at textures, colours, composition, emotions. Tell us a story! Draw us in. Show us life.</td>', 'Nice clock, but you need to develop your photographic eye. Did you think about the texture on the wall? The shadow cast by your light source? The glare caused by the light source? All these things take away from this shot. But the main question is why would we want to look at a centered composition of a clock?What story does it tell? ''Look Ma, I met the challenge'' is just not enough! Photography like this is perhaps good enough if you want to sell something on Ebay. If you want to be a photographer, look at textures, colours, composition, emotions. Tell us a story! Draw us in. Show us life.', '2005-12-20 07:09:28.000000', NULL, 1),
(1964505, 269004, 8522, '<td valign="top">Water seems OOF. I''m sure you could have made more of the silhouetted background, either by zooming out or in. At the moment, I don''t feel that the composition makes the most of them. Some PS work with curves could really bring out the colours in this shot.</td>', 'Water seems OOF. I''m sure you could have made more of the silhouetted background, either by zooming out or in. At the moment, I don''t feel that the composition makes the most of them. Some PS work with curves could really bring out the colours in this shot.', '2005-12-20 07:11:30.000000', NULL, 1),
(1964506, 268416, 8522, '<td valign="top">Huh? I don''t get this title. Are you saying the photo is not good? Why did you submit it then? Bad noise in this shot, you should try not to shoot at this ISO. Very uninspired composition. Why did you take this shot? What are you trying to communicate with it?</td>', 'Huh? I don''t get this title. Are you saying the photo is not good? Why did you submit it then? Bad noise in this shot, you should try not to shoot at this ISO. Very uninspired composition. Why did you take this shot? What are you trying to communicate with it?', '2005-12-20 07:12:57.000000', NULL, 1),
(1964507, 268561, 8522, '<td valign="top">This photo makes me feel dizzy... the building on the left is about to topple over.</td>', 'This photo makes me feel dizzy... the building on the left is about to topple over.', '2005-12-20 07:13:35.000000', NULL, 1),
(1964508, 266847, 8522, '<td valign="top">Nice colours, not a fan of centered compositions though. Why not place her on the right of the frame looking to the left? Bad JPEG artifacting, save with less compression. Why was this taken in landscape orientation? I''d have liked to see her right hand included in portrait orientation.</td>', 'Nice colours, not a fan of centered compositions though. Why not place her on the right of the frame looking to the left? Bad JPEG artifacting, save with less compression. Why was this taken in landscape orientation? I''d have liked to see her right hand included in portrait orientation.', '2005-12-20 07:14:49.000000', NULL, 1),
(1964551, 269004, 47455, '<td valign="top">nice image</td>', 'nice image', '2005-12-20 08:26:31.000000', NULL, 1),
(1964564, 268696, 9387, '<td valign="top">ORiginal thinking and good perspective.</td>', 'ORiginal thinking and good perspective.', '2005-12-20 08:53:25.000000', NULL, 1),
(1964565, 267033, 9387, '<td valign="top">excellent!</td>', 'excellent!', '2005-12-20 08:54:11.000000', NULL, 1),
(1964569, 266940, 9387, '<td valign="top">Good idea!</td>', 'Good idea!', '2005-12-20 08:55:40.000000', NULL, 1),
(1964570, 268865, 9387, '<td valign="top">nice shot.</td>', 'nice shot.', '2005-12-20 08:56:04.000000', NULL, 1),
(1964571, 269022, 9387, '<td valign="top">looks like 11:30 to me by military time.</td>', 'looks like 11:30 to me by military time.', '2005-12-20 08:57:03.000000', NULL, 1),
(1964572, 268883, 9387, '<td valign="top">great shot.</td>', 'great shot.', '2005-12-20 08:57:21.000000', NULL, 1),
(1964576, 266724, 9387, '<td valign="top">love your balcony.</td>', 'love your balcony.', '2005-12-20 08:58:09.000000', NULL, 1),
(1964578, 267071, 9387, '<td valign="top">too busy, too noisy and what is it?</td>', 'too busy, too noisy and what is it?', '2005-12-20 08:58:37.000000', NULL, 1),
(1964582, 269021, 9387, '<td valign="top">philadelphia at it''s finest.</td>', 'philadelphia at it''s finest.', '2005-12-20 08:59:55.000000', NULL, 1),
(1964585, 267576, 9387, '<td valign="top">I like it.</td>', 'I like it.', '2005-12-20 09:00:36.000000', NULL, 1),
(1964586, 268248, 9387, '<td valign="top">A lot to go through for a photo.</td>', 'A lot to go through for a photo.', '2005-12-20 09:01:10.000000', NULL, 1),
(1964588, 267742, 9387, '<td valign="top">The proof is in the clock.  Glad to see a few people actually got up that early.  LIke the shot too.</td>', 'The proof is in the clock.  Glad to see a few people actually got up that early.  LIke the shot too.', '2005-12-20 09:03:43.000000', NULL, 1),
(1964589, 267997, 9387, '<td valign="top">Very nice.</td>', 'Very nice.', '2005-12-20 09:04:03.000000', NULL, 1),
(1964591, 268348, 9387, '<td valign="top">I absolutely love this!</td>', 'I absolutely love this!', '2005-12-20 09:04:46.000000', NULL, 1),
(1964593, 267110, 47455, '<td valign="top">nice image</td>', 'nice image', '2005-12-20 09:05:18.000000', NULL, 1),
(1964595, 267033, 47455, '<td valign="top">voted 10! wonderful image!</td>', 'voted 10! wonderful image!', '2005-12-20 09:05:39.000000', NULL, 1),
(1964596, 268889, 47455, '<td valign="top">voted 10! wonderful image!</td>', 'voted 10! wonderful image!', '2005-12-20 09:06:14.000000', NULL, 1),
