(1966760, 267110, 12253, '<td valign="top">Woo Hoo! Congratulations on #2 skip, and a blue!  Wow, and I just noticed 8.3!<br/><br/><i>Message edited by author 2005-12-21 01:53:44.</i></td>', 'Woo Hoo! Congratulations on #2 skip, and a blue!  Wow, and I just noticed 8.3!', '2005-12-21 01:53:16.000000', '2005-12-21 01:53:44.000000', 0),
