(1971531, 267110, 31443, '<td valign="top">Glad to see this shot win the blue, can look at his image forever, better snatch it to my fav''s</td>', 'Glad to see this shot win the blue, can look at his image forever, better snatch it to my fav''s', '2005-12-22 15:11:02.000000', NULL, 0),
